/// 单次编译上限, 防止脚本写出无限循环时把内存吃光.
const MAX_STATEMENTS: usize = 100_000;
/// 单次导出最长 6 小时；同时避免时间戳和音频缓冲无限增长。
const MAX_DURATION_US: u64 = 6 * 60 * 60 * 1_000_000;

/// 调用栈帧。
#[derive(Debug)]
struct Frame {
    scene: String,
    line: usize,
}

/// 当前背景状态。
#[derive(Debug, Clone)]
struct BackgroundState {
    asset: String,
    transform: Transform,
}

/// 当前立绘状态。
#[derive(Debug, Clone)]
struct FigureState {
    track: usize,
    asset: Option<String>,
    live2d: Option<String>,
    expression: Option<String>,
    motion: Option<String>,
    /// 当前 motion 的起播时间; 只改表情时不重置。
    motion_start_us: u64,
    side: FigureSide,
    transform: Transform,
}

/// 导出起点; 默认是 `start.txt`.
#[derive(Debug, Clone, Default)]
pub struct StartOptions {
    pub scene: Option<String>,
    pub label: Option<String>,
}

/// 编译一个项目为 plan。
pub fn compile(project: &Project, config: &ExportConfig, policy: &ChoicePolicy) -> Result<Plan> {
    compile_with(project, config, policy, &StartOptions::default())
}

/// 从指定场景/标签编译。
pub fn compile_with(
    project: &Project,
    config: &ExportConfig,
    policy: &ChoicePolicy,
    start: &StartOptions,
) -> Result<Plan> {
    let scene = if let Some(name) = start.scene.as_deref() {
        project
            .scene(name)
            .map(|entry| entry.name.clone())
            .ok_or_else(|| Error::Unsupported(format!("起始场景不存在: {name}")))?
    } else {
        start_scene(project)?
    };
    let mut compiler = Compiler::new(project, config, policy, scene.clone());
    if let Some(label) = start.label.as_deref() {
        let line = compiler
            .labels
            .get(&scene)
            .and_then(|labels| labels.get(label))
            .copied()
            .ok_or_else(|| Error::Unsupported(format!("起始标签不存在: {label} ({scene})")))?;
        compiler.line = line;
    }
    compiler.run()?;
    Ok(compiler.finish())
}

fn start_scene(project: &Project) -> Result<String> {
    project
        .scene("start.txt")
        .or_else(|| project.scene("start"))
        .or_else(|| project.scenes().next().map(|(_, entry)| entry))
        .map(|entry| entry.name.clone())
        .ok_or_else(|| Error::InvalidProject {
            path: project.root().to_path_buf(),
            missing: "start.txt".to_owned(),
        })
}

struct Compiler<'a> {
    project: &'a Project,
    config: &'a ExportConfig,
    timing: Timing,
    policy: &'a ChoicePolicy,
    /// 已解析的 `changeFigure` 身份口径 (auto 在这里变成 legacy/modern)。
    figure_side: FigureSideMode,
    plan: Plan,
    background: Option<BackgroundState>,
    /// 整舞台变换 (只用 alpha); 供 `setTransform -target=stage-main` 累积。
    stage_transform: Transform,
    figures: BTreeMap<String, FigureState>,
    mini_avatar: Option<String>,
    scene: String,
    line: usize,
    stack: Vec<Frame>,
    labels: HashMap<String, HashMap<String, usize>>,
    visited: HashSet<(String, usize, usize)>,
    time_us: u64,
    steps: usize,
    last_text: Option<usize>,
    finished: bool,
    /// 脚本坐标 (默认 2560×1440) → 导出画面坐标的缩放系数。
    ///
    /// WebGAL 的舞台是 `game/config.txt` 里的 `Stage_Width/Height`, 脚本里的
    /// `-transform` 位置全部按这个坐标系书写; 导出画面通常更小, 必须整体缩放,
    /// 否则会看到"放大后又偏移"的构图。
    coordinate_scale: f32,
}

impl<'a> Compiler<'a> {
    fn new(
        project: &'a Project,
        config: &'a ExportConfig,
        policy: &'a ChoicePolicy,
        start: String,
    ) -> Self {
        let (stage_w, _) = project.stage_size();
        let coordinate_scale = config.video.width as f32 / stage_w as f32;
        let figure_side = config
            .figure_side
            .resolve(project.webgal_version().as_deref());
        Self {
            project,
            config,
            timing: Timing::new(&config.timing),
            policy,
            figure_side,
            plan: Plan {
                meta: Meta {
                    project_root: path_string(project.root()),
                    stage_w: config.video.width,
                    stage_h: config.video.height,
                    output_w: config.video.width,
                    output_h: config.video.height,
                    fps_num: config.video.fps,
                    fps_den: 1,
                    font_scale: config.font_scale,
                    disable_filters: config.disable_filters,
                    ..Meta::default()
                },
                ..Plan::default()
            },
            background: None,
            stage_transform: Transform::default(),
            figures: BTreeMap::new(),
            mini_avatar: None,
            scene: start,
            line: 0,
            stack: Vec::new(),
            labels: collect_labels(project),
            visited: HashSet::new(),
            time_us: 0,
            steps: 0,
            last_text: None,
            finished: false,
            coordinate_scale,
        }
    }

    fn run(&mut self) -> Result<()> {
        while !self.finished {
            if self.steps >= MAX_STATEMENTS {
                return Err(Error::Unsupported(format!(
                    "脚本超过 {MAX_STATEMENTS} 条语句, 可能是无限循环"
                )));
            }
            if self.time_us > MAX_DURATION_US {
                return Err(Error::Unsupported("视频超过 6 小时上限".to_owned()));
            }
            self.steps += 1;

            let scene = self
                .project
                .scene(&self.scene)
                .ok_or_else(|| Error::Unsupported(format!("场景不存在: {}", self.scene)))?;
            let sentence_count = scene.scene.sentences().len();
            if self.line >= sentence_count {
                let Some(frame) = self.stack.pop() else {
                    break;
                };
                self.scene = frame.scene;
                self.line = frame.line;
                continue;
            }

            let sentence = scene.scene.sentences()[self.line].sentence.clone();
            let line = self.line + 1;
            let key = (self.scene.clone(), self.line, self.stack.len());
            if !self.visited.insert(key) {
                return Err(Error::Unsupported(format!(
                    "检测到循环: {}:{line}",
                    self.scene
                )));
            }

            if let Some(condition) = sentence.condition()
                && !evaluate_condition(condition)?
            {
                self.line += 1;
                continue;
            }

            match &sentence {
                Sentence::Say(sentence) => {
                    self.say(sentence)?;
                    self.line += 1;
                }
                Sentence::ChangeBackground(sentence) => {
                    self.change_background(sentence)?;
                    self.line += 1;
                }
                Sentence::ChangeFigure(sentence) => {
                    self.change_figure(sentence)?;
                    self.line += 1;
                }
                Sentence::Bgm(sentence) => {
                    self.bgm(sentence)?;
                    self.line += 1;
                }
                Sentence::PlayEffect(sentence) => {
                    self.play_effect(sentence)?;
                    self.line += 1;
                }
                Sentence::PlayVideo(sentence) => {
                    self.play_video(sentence, line)?;
                    self.line += 1;
                }
                Sentence::Intro(sentence) => {
                    self.intro(sentence)?;
                    self.line += 1;
                }
                Sentence::Wait(sentence) => {
                    self.wait(sentence);
                    self.line += 1;
                }
                Sentence::SetTransform(sentence) => {
                    self.set_transform(sentence, line)?;
                    self.line += 1;
                }
                Sentence::Choose(sentence) => {
                    self.choose(sentence, line)?;
                }
                Sentence::CallScene(sentence) => {
                    self.call_scene(sentence)?;
                }
                Sentence::ChangeScene(sentence) => {
                    self.change_scene(sentence)?;
                }
                Sentence::JumpLabel(sentence) => {
                    self.jump_label(&sentence.label)?;
                }
                Sentence::Return(_) => {
                    if let Some(frame) = self.stack.pop() {
                        self.scene = frame.scene;
                        self.line = frame.line;
                    } else {
                        self.finished = true;
                    }
                }
                Sentence::End(_) => {
                    self.finished = true;
                }
                Sentence::Label(_) | Sentence::Comment(_) => {
                    self.line += 1;
                }
                Sentence::MiniAvatar(sentence) => {
                    self.mini_avatar = sentence.avatar.clone();
                    self.line += 1;
                }
                Sentence::SetTextbox(_) => {
                    self.warn("WG_TEXTBOX", "setTextbox 不改变导出 UI 状态", line);
                    self.line += 1;
                }
                Sentence::FilmMode(_) | Sentence::PixiInit(_) | Sentence::PixiPerform(_) => {
                    self.warn("WG_UNSUPPORTED_EFFECT", "特效/电影模式不参与导出", line);
                    self.line += 1;
                }
                Sentence::UnlockCg(_) | Sentence::UnlockBgm(_) | Sentence::CallSteam(_) => {
                    self.line += 1;
                }
                Sentence::SetAnimation(_)
                | Sentence::SetComplexAnimation(_)
                | Sentence::SetTempAnimation(_)
                | Sentence::SetTransition(_) => {
                    self.warn("WG_UNSUPPORTED_ANIMATION", "动画语句暂不生成关键帧", line);
                    self.line += 1;
                }
                Sentence::ApplyStyle(_) => {
                    self.warn("WG_UNSUPPORTED_STYLE", "applyStyle 不参与导出", line);
                    self.line += 1;
                }
                Sentence::SetVariable(sentence) => {
                    return Err(Error::Unsupported(format!(
                        "暂不支持变量: {} ({}:{line})",
                        sentence.expression.0, self.scene
                    )));
                }
                Sentence::GetUserInput(sentence) => {
                    return Err(Error::Unsupported(format!(
                        "暂不支持 getUserInput: {} ({}:{line})",
                        sentence.variable, self.scene
                    )));
                }
                Sentence::ShowVariables(_) => {
                    return Err(Error::Unsupported(format!(
                        "暂不支持 showVars ({}:{line})",
                        self.scene
                    )));
                }
            }
        }
        Ok(())
    }

    fn finish(mut self) -> Plan {
        self.plan.meta.format_version = FORMAT_VERSION;
        self.plan.meta.duration_us =
            (self.time_us + Timing::ms(self.config.timing.end_tail_ms)).min(MAX_DURATION_US);
        self.plan
    }

    fn say(&mut self, sentence: &SaySentence) -> Result<()> {
        let raw_text = sentence.content.join("|");
        let lines = raw_text
            .split('|')
            .map(|line| TextLine {
                chars: line
                    .chars()
                    .map(|character| TextChar {
                        text: character.to_string(),
                        style: None,
                        ruby: None,
                    })
                    .collect(),
            })
            .collect::<Vec<_>>();
        let char_count = raw_text
            .chars()
            .filter(|character| *character != '|')
            .count();

        let vocal = sentence
            .vocal
            .as_deref()
            .filter(|value| looks_like_audio(value))
            .map(|value| self.add_asset("vocal", value, AssetKind::Vocal))
            .transpose()?;
        let say_ms = if sentence.notend {
            0
        } else {
            self.timing.say_ms(char_count, 0)
        };
        let start = self.time_us;
        let end = start.saturating_add(say_ms * 1000);

        if let Some(vocal) = &vocal {
            self.plan.audio.push(AudioEvent {
                start_us: start,
                end_us: Some(end),
                path: vocal.clone(),
                kind: AudioKind::Vocal,
                volume: 1.0,
                fade_in_ms: 0,
                fade_out_ms: 0,
                loop_: false,
            });
        }

        let segment = TextSegment {
            start_us: start,
            end_us: end,
            speaker: sentence.speaker.clone().unwrap_or_default(),
            lines,
            font_size: sentence.font_size.to_string(),
            reveal_ms_per_char: self.timing.text_delay_ms.round() as u32,
            fade_ms: self.timing.text_anim_ms,
            vocal,
            figure: sentence.figure.as_ref().map(ToString::to_string),
            mini_avatar: self.mini_avatar.clone(),
            clear: !sentence.concat,
            notend: sentence.notend,
        };

        if sentence.concat
            && let Some(index) = self.last_text
            && let Some(previous) = self.plan.texts.get_mut(index)
        {
            previous.lines.extend(segment.lines);
            previous.end_us = previous.end_us.max(segment.end_us);
            if !sentence.notend {
                self.time_us = previous.end_us;
            }
        } else {
            self.plan.texts.push(segment);
            self.last_text = Some(self.plan.texts.len() - 1);
            if !sentence.notend {
                self.time_us = end;
            }
        }
        Ok(())
    }

    fn change_background(&mut self, sentence: &ChangeBackgroundSentence) -> Result<()> {
        let asset = sentence
            .background
            .as_deref()
            .map(|value| self.add_asset("background", value, AssetKind::Background))
            .transpose()?;
        let previous_asset = self.background.as_ref().map(|state| state.asset.clone());
        let transform = merge_transform(
            self.background
                .as_ref()
                .map(|state| &state.transform)
                .unwrap_or(&Transform::default()),
            sentence.transform.as_ref(),
        );
        // WebGAL: changeBg 的入场时长 = `-enterDuration` ?? `-duration` ?? 默认 1500ms。
        let enter_ms = sentence
            .enter_duration
            .or(sentence.duration)
            .unwrap_or(1500);
        let exit_ms = sentence.exit_duration.unwrap_or(1500);
        // 换图时引擎会先移除旧 effect, 新图的变换直接生效, 只有透明度过渡。
        let same_asset = asset.is_some() && previous_asset == asset;
        self.plan.background.push(BackgroundKey {
            t_us: self.time_us,
            asset: asset.clone(),
            transform: scale_transform(&transform, self.coordinate_scale),
            alpha: transform.alpha.unwrap_or(1.0),
            enter_ms,
            exit_ms,
            ease: sentence.ease.to_string(),
            snap_transform: !same_asset,
        });
        self.background = asset.map(|asset| BackgroundState { asset, transform });
        if sentence.forward == Forward::Wait {
            self.time_us = self.time_us.saturating_add(Timing::ms(enter_ms));
        }
        Ok(())
    }

    fn change_figure(&mut self, sentence: &ChangeFigureSentence) -> Result<()> {
        let id = sentence.get_id().to_string();
        let raw = sentence.figure.as_deref();
        let mut is_live2d = false;
        let (asset, live2d) = if let Some(value) = raw {
            let (kind, path) = FigureKind::from_path(value);
            if kind == FigureKind::Live2d {
                let resolved = self
                    .project
                    .asset_path("figure", path)
                    .ok_or_else(|| Error::Unsupported(format!("Live2D 模型不存在: {value}")))?;
                if !is_moc3(&resolved) {
                    return Err(Error::Unsupported(format!(
                        "不支持 Cubism 2 模型 (只有 .moc): {value}; 请使用 moc3"
                    )));
                }
                is_live2d = true;
            } else if kind != FigureKind::Image {
                return Err(Error::Unsupported(format!(
                    "当前只支持图片/Live2D 立绘, 当前为 {kind:?}: {value}"
                )));
            }
            let path = self.add_asset(
                "figure",
                path,
                if is_live2d {
                    AssetKind::Live2d
                } else {
                    AssetKind::Figure
                },
            )?;
            if is_live2d {
                (None, Some(path))
            } else {
                (Some(path), None)
            }
        } else {
            (None, None)
        };
        if is_live2d && (sentence.blink.is_some() || sentence.focus.is_some()) {
            self.warn(
                "WG_LIVE2D_STATIC",
                "blink/focus 尚未接入 Live2D，motion/expression 仍会应用",
                self.line + 1,
            );
        }
        let previous = self.figures.get(&id);
        let modern = self.figure_side == FigureSideMode::Modern;
        // 4.6.3 及以前: 未写 `-left/-right` 时沿用旧基准 (自由立绘不会因为省略位置
        // 而重置)。4.6.4 起: 省略位置等于 `center`, 位置参与身份判定。
        let effective_side = if !modern && sentence.side == FigureSide::Center {
            previous
                .map(|state| state.side)
                .unwrap_or(FigureSide::Center)
        } else {
            sentence.side
        };
        let same_figure = previous
            .map(|state| state.asset == asset && state.live2d == live2d)
            .unwrap_or(false);
        let side_changed = previous
            .map(|state| state.side != effective_side)
            .unwrap_or(false);
        // 身份变化 (换模型/换基准位置) 时引擎会移除旧 effect 再建新对象,
        // 新对象从默认变换开始, 不能继承上一张立绘的 `position.x`。
        let identity_same = same_figure && !(modern && side_changed);
        let default_transform = Transform::default();
        let base = if identity_same {
            previous
                .map(|state| &state.transform)
                .unwrap_or(&default_transform)
        } else {
            &default_transform
        };
        let transform = merge_transform(base, sentence.transform.as_ref());
        // `-transform position.x` 是相对立绘基准位置的偏移 (引擎里 container.x 相对 baseX);
        // 基准位置由 `-left/-right/...` 决定。基准值在写关键帧时加进去, 状态里仍存相对值,
        // 这样 setTransform 的增量语义不会被破坏。
        let base_x = side_base(effective_side);
        let z_index = sentence.z_index.map(i32::from).unwrap_or(0);
        let enter_ms = sentence.enter_duration.or(sentence.duration).unwrap_or(300);
        let exit_ms = sentence.exit_duration.unwrap_or(450);

        let track = if let Some(state) = previous {
            state.track
        } else {
            let track = self.plan.figures.len();
            self.plan.figures.push(FigureTrack {
                id: id.clone(),
                z_index,
                blend: BlendMode::Normal,
                keys: Vec::new(),
                poses: Vec::new(),
            });
            track
        };
        self.plan.figures[track].z_index = z_index;
        let transform_changed = previous
            .map(|state| state.transform != transform)
            .unwrap_or(true);
        let visible = asset.is_some() || live2d.is_some();
        // 旧版显式改基准时不会新建立绘, 但基准变了; 需要落一个关键帧把世界坐标挪过去。
        let legacy_side_jump = !modern && side_changed && same_figure;
        if !identity_same || transform_changed || !visible || legacy_side_jump {
            // 换立绘(身份变化)时引擎会先移除旧 effect, 新立绘直接落在目标变换上,
            // 入场动画只做 alpha 0 → 1; 同一立绘只改 transform 时才插值。
            // 基准位置变化本身没有过渡, 旧版也要直接落到新基准, 否则会滑过去。
            let snap_transform = previous.is_none() || !same_figure || side_changed;
            self.plan.figures[track].keys.push(FigureKey {
                t_us: self.time_us,
                asset: asset.clone(),
                live2d: live2d.clone(),
                expression: None,
                motion: None,
                transform: scale_transform(&with_base(&transform, base_x), self.coordinate_scale),
                alpha: transform.alpha.unwrap_or(1.0),
                visible,
                // 旧版改基准是瞬间落位, 不应顺带淡入。
                enter_ms: if legacy_side_jump { 0 } else { enter_ms },
                exit_ms,
                figure_switch: modern && side_changed,
                ease: sentence.ease.to_string(),
                snap_transform,
            });
            if sentence.forward == Forward::Wait {
                self.time_us = self.time_us.saturating_add(Timing::ms(enter_ms));
            }
        }
        let requested_expression = sentence
            .expression
            .as_deref()
            .filter(|value| !value.is_empty())
            .map(str::to_owned);
        let requested_motion = sentence
            .motion
            .as_deref()
            .filter(|value| !value.is_empty())
            .map(str::to_owned);
        // 同一身份下, 未写 `-expression/-motion` 时保留旧状态; 换模型时清空。
        // 只改表情的语句不能把 motion 状态一起清掉, 否则后续动作会从默认姿势开始。
        let expression = if identity_same {
            requested_expression
                .clone()
                .or_else(|| previous.and_then(|state| state.expression.clone()))
        } else {
            requested_expression.clone()
        };
        let motion = if identity_same {
            requested_motion
                .clone()
                .or_else(|| previous.and_then(|state| state.motion.clone()))
        } else {
            requested_motion.clone()
        };
        // 只有显式 `-motion` 才重新起播; 表情事件沿用已有 motion 的起点,
        // 否则动作会在每次改表情时倒回第一帧。
        let motion_start_us = if motion.is_none() {
            0
        } else if requested_motion.is_some() {
            self.time_us
        } else {
            previous
                .map(|state| state.motion_start_us)
                .unwrap_or(self.time_us)
        };
        if visible && (requested_motion.is_some() || requested_expression.is_some()) {
            self.plan.figures[track].poses.push(FigurePose {
                t_us: self.time_us,
                motion_start_us,
                motion: motion.clone(),
                expression: expression.clone(),
            });
        }
        if asset.is_some() || live2d.is_some() {
            self.figures.insert(
                id,
                FigureState {
                    track,
                    asset,
                    live2d,
                    expression,
                    motion,
                    motion_start_us,
                    side: effective_side,
                    transform,
                },
            );
        } else {
            self.figures.remove(&id);
        }
        Ok(())
    }

    fn set_transform(&mut self, sentence: &SetTransformSentence, line: usize) -> Result<()> {
        let duration_ms = sentence.duration.unwrap_or(500);
        // 变换从语句执行处开始，在 duration 内完成；`-next` 只是不阻塞后续语句。
        let at = self.time_us;
        let ease = sentence.ease.to_string();
        let target = sentence
            .target
            .as_ref()
            .map(ToString::to_string)
            .unwrap_or_else(|| "stage-main".to_owned());

        if target == "bg-main" {
            if let Some(state) = &self.background {
                let transform = merge_transform(&state.transform, Some(&sentence.transform));
                self.plan.background.push(BackgroundKey {
                    t_us: at,
                    asset: Some(state.asset.clone()),
                    alpha: transform.alpha.unwrap_or(1.0),
                    transform: scale_transform(&transform, self.coordinate_scale),
                    enter_ms: duration_ms,
                    exit_ms: 0,
                    ease: ease.clone(),
                    snap_transform: false,
                });
                self.background = Some(BackgroundState {
                    asset: state.asset.clone(),
                    transform,
                });
            } else {
                self.warn(
                    "WG_TRANSFORM_TARGET",
                    "背景尚未出现, setTransform 忽略",
                    line,
                );
            }
        } else if target == "stage-main" {
            // 整舞台只处理 alpha: 渲染器把 scene 画完后用黑场叠加 (1-alpha),
            // 文本/选项不受影响 —— 与引擎的 stage-main 容器语义一致。
            let transform = merge_transform(&self.stage_transform, Some(&sentence.transform));
            self.plan.stage.push(StageKey {
                t_us: at,
                alpha: transform.alpha.unwrap_or(1.0),
                enter_ms: duration_ms,
                ease: ease.clone(),
            });
            self.stage_transform = transform;
        } else if let Some(state) = self.figures.get(&target).cloned() {
            let track = state.track;
            let transform = merge_transform(&state.transform, Some(&sentence.transform));
            self.plan.figures[track].keys.push(FigureKey {
                t_us: at,
                asset: state.asset.clone(),
                live2d: state.live2d.clone(),
                expression: state.expression.clone(),
                motion: state.motion.clone(),
                alpha: transform.alpha.unwrap_or(1.0),
                transform: scale_transform(
                    &with_base(&transform, side_base(state.side)),
                    self.coordinate_scale,
                ),
                visible: true,
                enter_ms: duration_ms,
                exit_ms: 0,
                figure_switch: false,
                ease,
                snap_transform: false,
            });
            self.figures
                .insert(target, FigureState { transform, ..state });
        } else {
            self.warn(
                "WG_TRANSFORM_TARGET",
                &format!("立绘不存在: {target}"),
                line,
            );
        }

        if sentence.forward == Forward::Wait && !sentence.parallel {
            self.time_us = self.time_us.saturating_add(Timing::ms(duration_ms));
        }
        Ok(())
    }

    fn bgm(&mut self, sentence: &BgmSentence) -> Result<()> {
        for event in self.plan.audio.iter_mut().rev() {
            if event.kind == AudioKind::Bgm && event.end_us.is_none() {
                event.end_us = Some(self.time_us);
                break;
            }
        }
        let Some(bgm) = &sentence.bgm else {
            return Ok(());
        };
        let path = self.add_asset("bgm", bgm, AssetKind::Bgm)?;
        self.plan.audio.push(AudioEvent {
            start_us: self.time_us,
            end_us: None,
            path,
            kind: AudioKind::Bgm,
            volume: volume(sentence.volume),
            fade_in_ms: sentence.enter.unwrap_or(0),
            fade_out_ms: 0,
            loop_: true,
        });
        Ok(())
    }

    fn play_effect(&mut self, sentence: &PlayEffectSentence) -> Result<()> {
        let Some(effect) = &sentence.vocal else {
            return Ok(());
        };
        if !looks_like_audio(effect) {
            return Ok(());
        }
        let path = self.add_asset("vocal", effect, AssetKind::Vocal)?;
        self.plan.audio.push(AudioEvent {
            start_us: self.time_us,
            end_us: None,
            path,
            kind: AudioKind::Effect,
            volume: volume(sentence.volume),
            fade_in_ms: 0,
            fade_out_ms: 0,
            loop_: false,
        });
        Ok(())
    }

    fn play_video(&mut self, sentence: &PlayVideoSentence, line: usize) -> Result<()> {
        let path = self.add_asset("video", &sentence.video, AssetKind::Video)?;
        self.warn(
            "WG_VIDEO_DURATION",
            "视频时长尚未探测, plan 中先按 0 处理",
            line,
        );
        self.plan.videos.push(VideoSegment {
            start_us: self.time_us,
            end_us: self.time_us,
            path,
            fit: "contain".to_owned(),
        });
        Ok(())
    }

    fn intro(&mut self, sentence: &IntroSentence) -> Result<()> {
        let lines = sentence
            .content
            .join("|")
            .split('|')
            .map(str::to_owned)
            .collect::<Vec<_>>();
        let background = sentence
            .background_image
            .as_deref()
            .map(|value| self.add_asset("background", value, AssetKind::Background))
            .transpose()?;
        let start = self.time_us;
        let end = if sentence.hold {
            start + Timing::ms(self.timing.intro_hold_ms)
        } else {
            start
                + self
                    .timing
                    .intro_ms(lines.len(), sentence.delay.unwrap_or(0))
                    * 1000
        };
        self.plan.intros.push(IntroSegment {
            start_us: start,
            end_us: end,
            lines,
            font_size: sentence.font_size.to_string(),
            color: color(sentence.font_color),
            background,
            animation: sentence.animation.to_string(),
        });
        self.time_us = end;
        Ok(())
    }

    fn wait(&mut self, sentence: &WaitSentence) {
        self.time_us = self.time_us.saturating_add(Timing::ms(sentence.duration));
    }

    fn choose(&mut self, sentence: &ChooseSentence, line: usize) -> Result<()> {
        let options = sentence
            .choices
            .iter()
            .map(|choice| ChoiceOption {
                prompt: choice.prompt.clone(),
                target: choice.target.clone(),
            })
            .collect::<Vec<_>>();
        if options.is_empty() {
            return Err(Error::Unsupported(format!(
                "choose 没有选项 ({}:{line})",
                self.scene
            )));
        }
        let selected =
            self.policy
                .choose(&self.scene, line, options.len(), sentence.default_choice);
        let start = self.time_us;
        let end = start + Timing::ms(self.timing.choice_show_ms);
        self.plan.choices.push(ChoiceSegment {
            start_us: start,
            end_us: end,
            options: options.clone(),
            selected,
        });
        self.time_us = end;

        if let Some(target) = options[selected].target.as_deref() {
            if self.project.scene(target).is_some() {
                self.change_scene_name(target);
            } else {
                self.jump_label(target)?;
            }
        } else {
            self.line += 1;
        }
        Ok(())
    }

    fn call_scene(&mut self, sentence: &CallSceneSentence) -> Result<()> {
        if !sentence.variables.is_empty() || sentence.write_return_to.is_some() {
            return Err(Error::Unsupported(
                "callScene 传参/返回值暂不支持".to_owned(),
            ));
        }
        if self.project.scene(&sentence.scene).is_none() {
            return Err(Error::Unsupported(format!(
                "场景不存在: {}",
                sentence.scene
            )));
        }
        self.stack.push(Frame {
            scene: self.scene.clone(),
            line: self.line + 1,
        });
        self.change_scene_name(&sentence.scene);
        Ok(())
    }

    fn change_scene(&mut self, sentence: &ChangeSceneSentence) -> Result<()> {
        if self.project.scene(&sentence.scene).is_none() {
            return Err(Error::Unsupported(format!(
                "场景不存在: {}",
                sentence.scene
            )));
        }
        self.change_scene_name(&sentence.scene);
        Ok(())
    }

    fn change_scene_name(&mut self, target: &str) {
        self.scene = self
            .project
            .scene(target)
            .map(|entry| entry.name.clone())
            .unwrap_or_else(|| target.to_owned());
        self.line = 0;
    }

    fn jump_label(&mut self, label: &str) -> Result<()> {
        let Some(line) = self
            .labels
            .get(&self.scene)
            .and_then(|labels| labels.get(label))
        else {
            return Err(Error::Unsupported(format!(
                "标签不存在: {label} ({})",
                self.scene
            )));
        };
        self.line = *line;
        Ok(())
    }

    fn add_asset(&mut self, kind_dir: &str, raw: &str, kind: AssetKind) -> Result<String> {
        let path = self
            .project
            .asset_path(kind_dir, raw)
            .ok_or_else(|| Error::Unsupported(format!("资源不存在: {raw} ({kind_dir})")))?;
        let relative = path
            .strip_prefix(self.project.game_dir())
            .unwrap_or(&path)
            .to_string_lossy()
            .replace('\\', "/");
        self.plan
            .assets
            .entry(relative.clone())
            .or_insert(AssetInfo {
                path: relative.clone(),
                kind,
                width: None,
                height: None,
                duration_us: None,
            });
        Ok(relative)
    }

    fn warn(&mut self, code: &str, message: &str, line: usize) {
        self.plan.warnings.push(Warning {
            code: code.to_owned(),
            message: message.to_owned(),
            scene: Some(self.scene.clone()),
            line: Some(line),
        });
    }
}

fn collect_labels(project: &Project) -> HashMap<String, HashMap<String, usize>> {
    let mut labels = HashMap::new();
    for (name, entry) in project.scenes() {
        let mut scene_labels = HashMap::new();
        // `Compiler::line` 是 0 起始下标，而 `sentences()` 给的是 1 起始行号。
        for (line, info) in entry.sentences() {
            if let Sentence::Label(sentence) = &info.sentence {
                scene_labels.insert(sentence.label.clone(), line - 1);
            }
        }
        labels.insert(name.to_owned(), scene_labels);
    }
    labels
}

fn evaluate_condition(expression: &Expression) -> Result<bool> {
    if !expression.variables().is_empty() {
        return Err(Error::Unsupported(format!(
            "when 条件依赖变量: {expression}"
        )));
    }
    let value = expression
        .evaluate(&EmptyEvaluationContext)
        .map_err(|error| Error::Unsupported(format!("when 求值失败: {error}")))?;
    Ok(value.is_truthy())
}

fn merge_transform(base: &Transform, patch: Option<&Transform>) -> Transform {
    let mut transform = base.clone();
    if let Some(patch) = patch {
        transform.merge(patch);
    }
    transform
}

/// 立绘基准 X (2560 舞台坐标)。WebGAL 的 `M_3_1_0` 定位: center 居中, left/right ±430。
fn side_base(side: FigureSide) -> f32 {
    match side {
        FigureSide::Left => -430.0,
        FigureSide::Left13 => -360.0,
        FigureSide::Left14 => -260.0,
        FigureSide::Right => 430.0,
        FigureSide::Right13 => 360.0,
        FigureSide::Right14 => 260.0,
        FigureSide::Center => 0.0,
    }
}

/// 把相对基准的 `position.x` 加上基准值; 其余字段原样保留。
fn with_base(transform: &Transform, base: f32) -> Transform {
    let mut result = transform.clone();
    let mut position = result.position.unwrap_or_default();
    position.x = Some(position.x.unwrap_or(0) + base as i32);
    result.position = Some(position);
    result
}

/// 把脚本坐标系里的 `position` 缩放到导出画面坐标。
///
/// 缩放、旋转、滤镜参数本身与分辨率无关, 只有位移需要按比例换算。
fn scale_transform(transform: &Transform, scale: f32) -> Transform {
    if (scale - 1.0).abs() < f32::EPSILON {
        return transform.clone();
    }
    let mut result = transform.clone();
    if let Some(position) = result.position.as_mut() {
        if let Some(x) = position.x {
            position.x = Some((x as f32 * scale).round() as i32);
        }
        if let Some(y) = position.y {
            position.y = Some((y as f32 * scale).round() as i32);
        }
    }
    // 倒角厚度是脚本坐标(2560 舞台)里的像素; 导出画面更小时要同比缩小,
    // 否则 720p 上的 8px 会比 2560 舞台上的 8px 粗一倍多。
    if let Some(thickness) = result.bevel_thickness
        && thickness > 0
    {
        result.bevel_thickness = Some(((f32::from(thickness) * scale).round() as u8).max(1));
    }
    // 泛光模糊半径同样是舞台坐标里的像素。
    if let Some(blur) = result.bloom_blur
        && blur > 0
    {
        result.bloom_blur = Some(((f32::from(blur) * scale).round() as u8).max(1));
    }
    result
}

fn volume(value: Option<u32>) -> f32 {
    value.unwrap_or(100).min(100) as f32 / 100.0
}

fn color(value: Option<webgal_language_core::element::Color>) -> String {
    let value = value.unwrap_or_default();
    format!(
        "rgba({}, {}, {}, {})",
        value.red, value.green, value.blue, value.alpha
    )
}
